import pandas as pd
import numpy as np
import json
import os

# ── Load Data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

# Parse string columns that need type conversion
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')
df['MEAN_MOTION'] = pd.to_numeric(df['MEAN_MOTION'], errors='coerce')
df['INCLINATION'] = pd.to_numeric(df['INCLINATION'], errors='coerce')

# Extract launch year from OBJECT_ID (first 4 chars)
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# ── KPIs ───────────────────────────────────────────────────────────────────
total_sats = len(df)

# Orbit classification using MEAN_MOTION thresholds
def classify_orbit(mm, ecc):
    if pd.isna(mm):
        return 'Unknown'
    if ecc is not None and ecc > 0.1 and mm < 12:
        return 'HEO'
    if mm > 14:
        return 'LEO'
    elif mm >= 1.8:
        return 'MEO'
    elif mm >= 0.9:
        return 'GEO'
    else:
        return 'HEO'

df['ORBIT_REGIME'] = df.apply(lambda r: classify_orbit(r['MEAN_MOTION'], r['ECCENTRICITY']), axis=1)

leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = leo_count / total_sats * 100

starlink_count = len(df[df['OBJECT_NAME'].str.startswith('STARLINK', na=False)])
median_inclination = df['INCLINATION'].median()
post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])

# ── Orbit Regime Distribution ──────────────────────────────────────────────
orbit_counts = df['ORBIT_REGIME'].value_counts().to_dict()

# ── Constellation Analysis ─────────────────────────────────────────────────
def extract_constellation(name):
    if pd.isna(name):
        return 'Other'
    name_upper = name.upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    elif name_upper.startswith('GPS') or 'NAVSTAR' in name_upper:
        return 'GPS'
    elif name_upper.startswith('COSMO') or name_upper.startswith('COSMO-SkyMed'):
        return 'COSMO-SkyMed'
    elif name_upper.startswith('GLONASS') or name_upper.startswith('COSMOS') and 'GLONASS' in name_upper:
        return 'GLONASS'
    elif 'GLOBALSTAR' in name_upper:
        return 'Globalstar'
    elif name_upper.startswith('GONETS'):
        return 'Gonets'
    elif name_upper.startswith('FLOCK'):
        return 'Flock (Planet)'
    elif name_upper.startswith('SKYSAT'):
        return 'SkySat (Planet)'
    elif name_upper.startswith('DOVE'):
        return 'Dove (Planet)'
    elif name_upper.startswith('SES'):
        return 'SES'
    elif name_upper.startswith('INTELSAT'):
        return 'Intelsat'
    elif name_upper.startswith('EUTELSAT') or name_upper.startswith('EUTEL'):
        return 'Eutelsat'
    elif name_upper.startswith('YAOGAN'):
        return 'Yaogan'
    elif name_upper.startswith('TIANLIAN'):
        return 'Tianlian'
    elif name_upper.startswith('BEIDOU') or name_upper.startswith('COMPASS') or name_upper.startswith('BD'):
        return 'BeiDou'
    elif name_upper.startswith('GALILEO') or name_upper.startswith('GSAT') and 'GALILEO' in name_upper:
        return 'Galileo'
    elif name_upper.startswith('SWARM') or name_upper.startswith('SWARM-'):
        return 'Swarm'
    elif name_upper.startswith('LEO') and 'SAT' in name_upper:
        return 'LEOSat'
    elif name_upper.startswith('NOAA') or name_upper.startswith('GOES') or name_upper.startswith('METOP') or name_upper.startswith('SUOMI') or name_upper.startswith('JPSS'):
        return 'Weather/Env'
    elif name_upper.startswith('TDRS'):
        return 'TDRS'
    elif name_upper.startswith('KH') or name_upper.startswith('USA') or name_upper.startswith('LACROSSE') or name_upper.startswith('ONION'):
        return 'US Military'
    elif name_upper.startswith('ISS') or name_upper.startswith('ZARYA') or name_upper.startswith('CYGNUS') or name_upper.startswith('DRAGON') or name_upper.startswith('PROGRESS') or name_upper.startswith('SOYUZ'):
        return 'Crewed/Cargo'
    elif name_upper.startswith('HUBBLE') or name_upper == 'HST':
        return 'Science'
    else:
        return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(extract_constellation)

# Top constellations
constellation_counts = df['CONSTELLATION'].value_counts()
top_constellations = constellation_counts.head(15)

# ── Launch Year Trends ─────────────────────────────────────────────────────
year_counts = df['LAUNCH_YEAR'].value_counts().sort_index()
# Cumulative
cumulative_counts = year_counts.sort_index().cumsum()

# ── Orbital Characteristics ────────────────────────────────────────────────
inclination_stats = df['INCLINATION'].describe()
eccentricity_stats = df['ECCENTRICITY'].describe()
mean_motion_stats = df['MEAN_MOTION'].describe()

# Inclination distribution buckets
incl_bins = [0, 10, 30, 50, 70, 90, 100, 110, 120, 180]
incl_labels = ['0-10°', '10-30°', '30-50°', '50-70°', '70-90°', '90-100°', '100-110°', '110-120°', '120-180°']
df['INCL_BUCKET'] = pd.cut(df['INCLINATION'], bins=incl_bins, labels=incl_labels, include_lowest=True)
incl_dist = df['INCL_BUCKET'].value_counts().sort_index()

# Eccentricity distribution buckets
ecc_bins = [0, 0.001, 0.005, 0.01, 0.05, 0.1, 0.5, 1.0]
ecc_labels = ['<0.001', '0.001-0.005', '0.005-0.01', '0.01-0.05', '0.05-0.1', '0.1-0.5', '0.5-1.0']
df['ECC_BUCKET'] = pd.cut(df['ECCENTRICITY'], bins=ecc_bins, labels=ecc_labels, include_lowest=True)
ecc_dist = df['ECC_BUCKET'].value_counts().sort_index()

# Mean Motion distribution
mm_bins = [0, 1.1, 2.5, 6, 11, 13, 14, 15, 16.5, 20]
mm_labels = ['0-1.1\n(GEO)', '1.1-2.5\n(MEO/HEO)', '2.5-6', '6-11', '11-13', '13-14', '14-15', '15-16.5', '16.5+']
df['MM_BUCKET'] = pd.cut(df['MEAN_MOTION'], bins=mm_bins, labels=mm_labels, include_lowest=True)
mm_dist = df['MM_BUCKET'].value_counts().sort_index()

# Starlink vs non-Starlink in LEO
leo_df = df[df['ORBIT_REGIME'] == 'LEO']
starlink_leo = len(leo_df[leo_df['CONSTELLATION'] == 'Starlink'])
non_starlink_leo = leo_count - starlink_leo

# Launch year data for chart
year_labels = [int(y) for y in year_counts.index]
year_values = [int(v) for v in year_counts.values]
cum_values = [int(v) for v in cumulative_counts.values]

# Top constellation data
const_labels = top_constellations.index.tolist()
const_values = [int(v) for v in top_constellations.values]

# Orbit regime data for pie
orbit_labels = list(orbit_counts.keys())
orbit_values = [int(v) for v in orbit_counts.values()]

# Inclination distribution
incl_labels_chart = incl_dist.index.tolist()
incl_values_chart = [int(v) for v in incl_dist.values]

# Eccentricity distribution
ecc_labels_chart = ecc_dist.index.tolist()
ecc_values_chart = [int(v) for v in ecc_dist.values]

# Mean motion distribution
mm_labels_chart = mm_dist.index.tolist()
mm_values_chart = [int(v) for v in mm_dist.values]

# ── Starlink launch year breakdown ─────────────────────────────────────────
starlink_df = df[df['CONSTELLATION'] == 'Starlink']
starlink_year = starlink_df['LAUNCH_YEAR'].value_counts().sort_index()
non_starlink_df = df[df['CONSTELLATION'] != 'Starlink']
non_starlink_year = non_starlink_df['LAUNCH_YEAR'].value_counts().sort_index()

# Align years
all_years = sorted(set(starlink_year.index) | set(non_starlink_year.index))
starlink_by_year = [int(starlink_year.get(y, 0)) for y in all_years]
non_starlink_by_year = [int(non_starlink_year.get(y, 0)) for y in all_years]

# ── EPOCH range ────────────────────────────────────────────────────────────
epoch_min = df['EPOCH'].min()[:10]
epoch_max = df['EPOCH'].max()[:10]

# ── Constellation orbit breakdown ──────────────────────────────────────────
top5_constellations = constellation_counts.head(8).index.tolist()
const_orbit_data = {}
for c in top5_constellations:
    c_df = df[df['CONSTELLATION'] == c]
    const_orbit_data[c] = c_df['ORBIT_REGIME'].value_counts().to_dict()

# ── Generate HTML ──────────────────────────────────────────────────────────
os.makedirs('/app/output', exist_ok=True)

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --primary: #0f2942;
    --secondary: #1a5276;
    --accent: #2e86c1;
    --accent-light: #85c1e9;
    --bg: #f8f9fa;
    --card-bg: #ffffff;
    --text: #2c3e50;
    --text-muted: #7f8c8d;
    --border: #e0e0e0;
    --success: #27ae60;
    --warning: #e67e22;
    --danger: #c0392b;
  }}

  * {{ margin: 0; padding: 0; box-sizing: border-box; }}

  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}

  .report-header {{
    background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
    color: #fff;
    padding: 48px 0 40px;
    text-align: center;
  }}

  .report-header h1 {{
    font-size: 2rem;
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 8px;
  }}

  .report-header .subtitle {{
    font-size: 1.05rem;
    opacity: 0.85;
    font-weight: 400;
  }}

  .report-header .meta {{
    font-size: 0.85rem;
    opacity: 0.6;
    margin-top: 12px;
  }}

  .container {{
    max-width: 1140px;
    margin: 0 auto;
    padding: 0 24px;
  }}

  /* KPI Strip */
  .kpi-strip {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin: -28px auto 36px;
    position: relative;
    z-index: 2;
  }}

  .kpi-card {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 22px 18px;
    text-align: center;
    box-shadow: 0 4px 20px rgba(0,0,0,0.08);
    border-top: 3px solid var(--accent);
  }}

  .kpi-card .kpi-value {{
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--primary);
    line-height: 1.2;
  }}

  .kpi-card .kpi-label {{
    font-size: 0.78rem;
    color: var(--text-muted);
    margin-top: 6px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 600;
  }}

  /* Sections */
  .section {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 32px;
    margin-bottom: 28px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.04);
  }}

  .section h2 {{
    font-size: 1.35rem;
    color: var(--primary);
    margin-bottom: 6px;
    font-weight: 700;
    border-bottom: 2px solid var(--accent);
    padding-bottom: 10px;
  }}

  .section h3 {{
    font-size: 1.05rem;
    color: var(--secondary);
    margin: 20px 0 10px;
    font-weight: 600;
  }}

  .section p, .section li {{
    font-size: 0.92rem;
    color: var(--text);
    line-height: 1.7;
  }}

  .section ul {{
    padding-left: 20px;
    margin: 10px 0;
  }}

  .section li {{
    margin-bottom: 4px;
  }}

  .chart-container {{
    position: relative;
    margin: 20px 0;
    width: 100%;
  }}

  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 20px 0;
  }}

  .chart-box {{
    background: #fafbfc;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 18px;
  }}

  .chart-box h4 {{
    font-size: 0.9rem;
    color: var(--secondary);
    margin-bottom: 12px;
    font-weight: 600;
  }}

  .callout {{
    background: #eaf2f8;
    border-left: 4px solid var(--accent);
    padding: 16px 20px;
    border-radius: 0 8px 8px 0;
    margin: 16px 0;
    font-size: 0.9rem;
  }}

  .callout strong {{
    color: var(--primary);
  }}

  .data-table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.88rem;
  }}

  .data-table th {{
    background: var(--primary);
    color: #fff;
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }}

  .data-table td {{
    padding: 9px 14px;
    border-bottom: 1px solid var(--border);
  }}

  .data-table tr:nth-child(even) td {{
    background: #f7f9fb;
  }}

  .data-table tr:hover td {{
    background: #eaf2f8;
  }}

  .badge {{
    display: inline-block;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: 0.78rem;
    font-weight: 600;
  }}

  .badge-leo {{ background: #d4efdf; color: #1e8449; }}
  .badge-meo {{ background: #fad7a0; color: #b9770e; }}
  .badge-geo {{ background: #d6eaf8; color: #2471a3; }}
  .badge-heo {{ background: #f5b7b1; color: #c0392b; }}

  .footer {{
    text-align: center;
    padding: 28px;
    color: var(--text-muted);
    font-size: 0.82rem;
  }}

  @media (max-width: 900px) {{
    .kpi-strip {{ grid-template-columns: repeat(3, 1fr); }}
    .chart-row {{ grid-template-columns: 1fr; }}
  }}

  @media (max-width: 600px) {{
    .kpi-strip {{ grid-template-columns: repeat(2, 1fr); }}
    .report-header h1 {{ font-size: 1.5rem; }}
  }}
</style>
</head>
<body>

<!-- ═══ HEADER ═══ -->
<div class="report-header">
  <div class="container">
    <h1>Active Satellites in Earth Orbit</h1>
    <div class="subtitle">2026 Catalog Analysis</div>
    <div class="meta">Data source: CelesTrak / NORAD TLE &middot; EPOCH range: {epoch_min} to {epoch_max}</div>
  </div>
</div>

<!-- ═══ KPI STRIP ═══ -->
<div class="container">
  <div class="kpi-strip">
    <div class="kpi-card">
      <div class="kpi-value">{total_sats:,}</div>
      <div class="kpi-label">Total Active Satellites</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{leo_share:.1f}%</div>
      <div class="kpi-label">LEO Share</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{starlink_count:,}</div>
      <div class="kpi-label">Starlink Constellation</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{median_inclination:.1f}°</div>
      <div class="kpi-label">Median Inclination</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">{post_2020_count:,}</div>
      <div class="kpi-label">Launched Since 2020</div>
    </div>
  </div>
</div>

<!-- ═══ SECTION 1: OVERVIEW ═══ -->
<div class="container">
  <div class="section">
    <h2>1. Catalog Overview &amp; Key Figures</h2>
    <p>
      This catalog contains <strong>{total_sats:,}</strong> active satellites tracked by NORAD and published via CelesTrak.
      The orbital element sets span from <strong>{epoch_min}</strong> to <strong>{epoch_max}</strong>,
      reflecting recent positional data for all operational spacecraft. The dataset includes
      civil, commercial, and military satellites across every orbital regime — from the
      International Space Station in low Earth orbit to geostationary communications platforms
      at 35,786 km altitude.
    </p>

    <div class="callout">
      <strong>Key structural insight:</strong> {starlink_count:,} of {total_sats:,} active satellites ({starlink_count/total_sats*100:.1f}%) belong to
      SpaceX's Starlink constellation. A single commercial operator thus controls more than half the
      active orbital population, profoundly shaping aggregate statistics for orbital regime, inclination,
      and launch cadence.
    </div>

    <h3>Summary Statistics</h3>
    <table class="data-table">
      <tr><th>Parameter</th><th>Mean</th><th>Median</th><th>Std Dev</th><th>Min</th><th>Max</th></tr>
      <tr><td>Mean Motion (rev/day)</td><td>{mean_motion_stats['mean']:.3f}</td><td>{mean_motion_stats['50%']:.3f}</td><td>{mean_motion_stats['std']:.3f}</td><td>{mean_motion_stats['min']:.3f}</td><td>{mean_motion_stats['max']:.3f}</td></tr>
      <tr><td>Inclination (°)</td><td>{inclination_stats['mean']:.2f}</td><td>{inclination_stats['50%']:.2f}</td><td>{inclination_stats['std']:.2f}</td><td>{inclination_stats['min']:.2f}</td><td>{inclination_stats['max']:.2f}</td></tr>
      <tr><td>Eccentricity</td><td>{eccentricity_stats['mean']:.6f}</td><td>{eccentricity_stats['50%']:.6f}</td><td>{eccentricity_stats['std']:.6f}</td><td>{eccentricity_stats['min']:.6f}</td><td>{eccentricity_stats['max']:.6f}</td></tr>
    </table>
  </div>
</div>

<!-- ═══ SECTION 2: ORBITAL REGIME ═══ -->
<div class="container">
  <div class="section">
    <h2>2. Orbital Regime Classification</h2>
    <p>
      Satellites are classified into four regimes using <strong>MEAN_MOTION</strong> thresholds
      supplemented by eccentricity checks for highly elliptical orbits:
    </p>
    <ul>
      <li><span class="badge badge-leo">LEO</span> — MEAN_MOTION &gt; 14 rev/day (approximately 160–2,000 km altitude)</li>
      <li><span class="badge badge-meo">MEO</span> — MEAN_MOTION 1.8–14 rev/day (approximately 2,000–35,786 km, excluding HEO)</li>
      <li><span class="badge badge-geo">GEO</span> — MEAN_MOTION 0.9–1.8 rev/day (approximately 35,786 km altitude)</li>
      <li><span class="badge badge-heo">HEO</span> — ECCENTRICITY &gt; 0.1 with MEAN_MOTION &lt; 12, or MEAN_MOTION &lt; 0.9</li>
    </ul>

    <div class="chart-row">
      <div class="chart-box">
        <h4>Distribution by Orbital Regime</h4>
        <div class="chart-container" style="max-height:340px;">
          <canvas id="orbitPieChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h4>Regime Breakdown</h4>
        <table class="data-table">
          <tr><th>Regime</th><th>Count</th><th>Share</th></tr>
          <tr><td><span class="badge badge-leo">LEO</span></td><td>{orbit_counts.get('LEO', 0):,}</td><td>{orbit_counts.get('LEO', 0)/total_sats*100:.1f}%</td></tr>
          <tr><td><span class="badge badge-geo">GEO</span></td><td>{orbit_counts.get('GEO', 0):,}</td><td>{orbit_counts.get('GEO', 0)/total_sats*100:.1f}%</td></tr>
          <tr><td><span class="badge badge-meo">MEO</span></td><td>{orbit_counts.get('MEO', 0):,}</td><td>{orbit_counts.get('MEO', 0)/total_sats*100:.1f}%</td></tr>
          <tr><td><span class="badge badge-heo">HEO</span></td><td>{orbit_counts.get('HEO', 0):,}</td><td>{orbit_counts.get('HEO', 0)/total_sats*100:.1f}%</td></tr>
        </table>
        <div class="callout" style="margin-top:14px;">
          <strong>LEO dominates:</strong> {orbit_counts.get('LEO', 0)/total_sats*100:.1f}% of all active satellites
          orbit in the LEO regime, driven primarily by mega-constellation deployments. Of the {leo_count:,} LEO
          satellites, {starlink_leo:,} ({starlink_leo/leo_count*100:.1f}%) are Starlink.
        </div>
      </div>
    </div>
  </div>
</div>

<!-- ═══ SECTION 3: CONSTELLATION ANALYSIS ═══ -->
<div class="container">
  <div class="section">
    <h2>3. Major Constellation &amp; Operator Breakdown</h2>
    <p>
      Constellation membership is determined by parsing the <strong>OBJECT_NAME</strong> prefix.
      The table below ranks the 15 largest identified constellations. Operators not matching
      known prefixes are aggregated as "Other."
    </p>

    <div class="chart-container" style="max-height:460px;">
      <canvas id="constellationChart"></canvas>
    </div>

    <table class="data-table">
      <tr><th>#</th><th>Constellation</th><th>Count</th><th>Share of Total</th><th>Dominant Regime</th></tr>
"""

# Build constellation table rows
for i, (name, count) in enumerate(top_constellations.items(), 1):
    orbit_breakdown = const_orbit_data.get(name, {})
    dominant = max(orbit_breakdown, key=orbit_breakdown.get) if orbit_breakdown else '—'
    badge_class = {'LEO': 'badge-leo', 'MEO': 'badge-meo', 'GEO': 'badge-geo', 'HEO': 'badge-heo'}.get(dominant, '')
    html += f"""      <tr><td>{i}</td><td>{name}</td><td>{count:,}</td><td>{count/total_sats*100:.1f}%</td><td><span class="badge {badge_class}">{dominant}</span></td></tr>\n"""

html += f"""    </table>

    <div class="callout">
      <strong>Starlink's gravitational pull on the data:</strong> With {starlink_count:,} satellites,
      SpaceX's Starlink alone accounts for {starlink_count/total_sats*100:.1f}% of all active satellites.
      Excluding Starlink, the remaining {total_sats - starlink_count:,} satellites are distributed across
      hundreds of operators and missions — the next largest identified constellation (OneWeb) holds just
      {constellation_counts.get('OneWeb', 0):,} satellites ({constellation_counts.get('OneWeb', 0)/total_sats*100:.1f}%).
    </div>
  </div>
</div>

<!-- ═══ SECTION 4: LAUNCH TRENDS ═══ -->
<div class="container">
  <div class="section">
    <h2>4. Launch Year Trends</h2>
    <p>
      The launch year is extracted from the first four characters of <strong>OBJECT_ID</strong>
      (the international designator). The charts below show the number of <em>currently active</em>
      satellites by launch year — not total historical launches, but the subset still operational in orbit today.
    </p>

    <div class="chart-container" style="max-height:420px;">
      <canvas id="launchTrendChart"></canvas>
    </div>

    <h3>Starlink vs. Non-Starlink Decomposition</h3>
    <p>
      To isolate the effect of mega-constellation deployments, the launch-year distribution
      is decomposed into Starlink and non-Starlink contributions:
    </p>

    <div class="chart-container" style="max-height:380px;">
      <canvas id="stackedLaunchChart"></canvas>
    </div>

    <div class="callout">
      <strong>Recent acceleration:</strong> Of the {total_sats:,} currently active satellites,
      {post_2020_count:,} ({post_2020_count/total_sats*100:.1f}%) were launched in 2020 or later.
      This reflects an unprecedented ramp-up driven almost entirely by Starlink deployments.
      The number of active satellites launched per year has increased by an order of magnitude
      compared to pre-2019 baselines.
    </div>

    <h3>Cumulative Active Fleet Growth</h3>
    <div class="chart-container" style="max-height:360px;">
      <canvas id="cumulativeChart"></canvas>
    </div>
  </div>
</div>

<!-- ═══ SECTION 5: ORBITAL CHARACTERISTICS ═══ -->
<div class="container">
  <div class="section">
    <h2>5. Orbital Parameter Deep Dive</h2>
    <p>
      The distributions of inclination, eccentricity, and mean motion reveal the dominant orbital
      shells and identify notable outliers such as polar sun-synchronous orbits, Molniya-type
      highly elliptical orbits, and geostationary platforms.
    </p>

    <div class="chart-row">
      <div class="chart-box">
        <h4>Inclination Distribution</h4>
        <div class="chart-container" style="max-height:300px;">
          <canvas id="inclChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h4>Eccentricity Distribution</h4>
        <div class="chart-container" style="max-height:300px;">
          <canvas id="eccChart"></canvas>
        </div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box" style="grid-column: 1 / -1;">
        <h4>Mean Motion Distribution</h4>
        <div class="chart-container" style="max-height:300px;">
          <canvas id="mmChart"></canvas>
        </div>
      </div>
    </div>

    <h3>Key Observations</h3>
    <ul>
      <li><strong>Sun-synchronous cluster:</strong> The 97–98° inclination bin contains {incl_dist.get('90-100°', 0):,}
          satellites, reflecting the popularity of sun-synchronous orbits (SSO) for Earth observation and weather missions.</li>
      <li><strong>Starlink shell at ~53°:</strong> The 50–70° bin is dominated by Starlink's nominal 53° and 53.2° orbital shells,
          contributing thousands of satellites in a narrow inclination band.</li>
      <li><strong>Low eccentricity norm:</strong> {ecc_dist.get('<0.001', 0) + ecc_dist.get('0.001-0.005', 0):,}
          satellites ({(ecc_dist.get('<0.001', 0) + ecc_dist.get('0.001-0.005', 0))/total_sats*100:.1f}%) have eccentricities below 0.005,
          indicating nearly circular orbits — typical of station-kept operational spacecraft.</li>
      <li><strong>HEO outliers:</strong> {ecc_dist.get('0.1-0.5', 0) + ecc_dist.get('0.5-1.0', 0):,}
          satellites exhibit eccentricities above 0.1, including Molniya and GTO-class orbits.</li>
      <li><strong>GEO concentration:</strong> A distinct peak near MEAN_MOTION ≈ 1.0 rev/day corresponds to the geostationary ring,
          hosting {orbit_counts.get('GEO', 0):,} active satellites.</li>
    </ul>
  </div>
</div>

<!-- ═══ SECTION 6: CONCLUSIONS ═══ -->
<div class="container">
  <div class="section">
    <h2>6. Key Takeaways &amp; Outlook</h2>
    <ul>
      <li><strong>LEO is now the overwhelmingly dominant regime</strong> — {leo_share:.1f}% of all active satellites
          orbit below ~2,000 km. This share is set to grow as Starlink, OneWeb, and planned constellations continue launching.</li>
      <li><strong>A single operator reshapes the statistics.</strong> Starlink's {starlink_count:,} satellites
          ({starlink_count/total_sats*100:.1f}% of the catalog) skew inclination distributions toward 53°, inflate LEO counts,
          and account for the majority of post-2020 launch activity. Any regulatory or policy analysis must
          segment by operator to avoid misleading aggregates.</li>
      <li><strong>Post-2020 launch surge is unprecedented.</strong> {post_2020_count:,} satellites
          ({post_2020_count/total_sats*100:.1f}%) were launched since 2020. This represents a step-change
          in orbital population growth, with implications for conjunction assessment, collision risk, and
          debris generation rates.</li>
      <li><strong>Orbital congestion is concentrated.</strong> The combination of high satellite density
          in the 500–600 km altitude band (Starlink) and the 97–98° sun-synchronous corridor creates
          localized congestion. Spectrum coordination and right-of-way norms will face increasing pressure.</li>
      <li><strong>GEO remains strategically vital despite its small share.</strong> With {orbit_counts.get('GEO', 0):,}
          active satellites ({orbit_counts.get('GEO', 0)/total_sats*100:.1f}%), GEO hosts the bulk of communications,
          weather, and early-warning missions that require persistent regional coverage.</li>
      <li><strong>Space sustainability requires action.</strong> The rapid growth of the LEO population,
          combined with planned mega-constellation filings (tens of thousands of additional satellites),
          demands proactive debris mitigation, active removal capabilities, and internationally coordinated
          traffic management to preserve the orbital environment for future use.</li>
    </ul>
  </div>
</div>

<div class="footer">
  <div class="container">
    Active Satellites in Earth Orbit — 2026 Catalog Analysis &middot; Data: CelesTrak / NORAD TLE &middot; Report generated from source data
  </div>
</div>

<!-- ═══ CHARTS ═══ -->
<script>
// Color palette
const C = {{
  primary: '#0f2942',
  accent: '#2e86c1',
  accentLight: '#85c1e9',
  leo: '#27ae60',
  meo: '#e67e22',
  geo: '#2e86c1',
  heo: '#c0392b',
  starlink: '#2e86c1',
  other: '#95a5a6',
  palette: ['#2e86c1','#27ae60','#e67e22','#c0392b','#8e44ad','#16a085','#d4ac0d','#2c3e50','#e74c3c','#1abc9c','#f39c12','#3498db','#9b59b6','#1e8449','#d35400']
}};

Chart.defaults.font.family = "'Segoe UI', system-ui, sans-serif";
Chart.defaults.font.size = 12;
Chart.defaults.plugins.legend.labels.usePointStyle = true;

// ── Orbit Regime Pie ──
new Chart(document.getElementById('orbitPieChart'), {{
  type: 'doughnut',
  data: {{
    labels: {json.dumps(orbit_labels)},
    datasets: [{{
      data: {json.dumps(orbit_values)},
      backgroundColor: [C.leo, C.geo, C.meo, C.heo],
      borderWidth: 2,
      borderColor: '#fff'
    }}]
  }},
  options: {{
    responsive: true,
    maintainAspectRatio: false,
    plugins: {{
      legend: {{ position: 'bottom', labels: {{ padding: 14 }} }},
      tooltip: {{
        callbacks: {{
          label: ctx => `${{ctx.label}}: ${{ctx.parsed.toLocaleString()}} (${{(ctx.parsed/{total_sats}*100).toFixed(1)}}%)`
        }}
      }}
    }}
  }}
}});

// ── Constellation Bar ──
new Chart(document.getElementById('constellationChart'), {{
  type: 'bar',
  data: {{
    labels: {json.dumps(const_labels)},
    datasets: [{{
      label: 'Active Satellites',
      data: {json.dumps(const_values)},
      backgroundColor: C.palette.slice(0, {len(const_labels)}),
      borderRadius: 4,
      maxBarThickness: 48
    }}]
  }},
  options: {{
    indexAxis: 'y',
    responsive: true,
    maintainAspectRatio: false,
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => `${{ctx.parsed.x.toLocaleString()}} satellites (${{(ctx.parsed.x/{total_sats}*100).toFixed(1)}}%)`
        }}
      }}
    }},
    scales: {{
      x: {{ title: {{ display: true, text: 'Number of Active Satellites' }}, grid: {{ color: '#eee' }} }},
      y: {{ grid: {{ display: false }} }}
    }}
  }}
}});

// ── Launch Trend (line + bar) ──
new Chart(document.getElementById('launchTrendChart'), {{
  type: 'bar',
  data: {{
    labels: {json.dumps(year_labels)},
    datasets: [{{
      label: 'Satellites Launched per Year (still active)',
      data: {json.dumps(year_values)},
      backgroundColor: year_labels.map(y => y >= 2020 ? C.accent : C.accentLight),
      borderRadius: 3,
      maxBarThickness: 28
    }}]
  }},
  options: {{
    responsive: true,
    maintainAspectRatio: false,
    plugins: {{
      legend: {{ display: true, position: 'top' }},
      tooltip: {{
        callbacks: {{
          label: ctx => `${{ctx.parsed.y.toLocaleString()}} currently active`
        }}
      }}
    }},
    scales: {{
      y: {{
        title: {{ display: true, text: 'Number of Active Satellites' }},
        grid: {{ color: '#eee' }},
        beginAtZero: true
      }},
      x: {{
        grid: {{ display: false }},
        ticks: {{ maxRotation: 60 }}
      }}
    }}
  }}
}});

// ── Stacked Launch Chart ──
new Chart(document.getElementById('stackedLaunchChart'), {{
  type: 'bar',
  data: {{
    labels: {json.dumps([int(y) for y in all_years])},
    datasets: [
      {{
        label: 'Starlink',
        data: {json.dumps(starlink_by_year)},
        backgroundColor: C.starlink,
